using Alterverse.Characters;using UnityEngine;
namespace Alterverse.Combat
{
[RequireComponent(typeof(Health))]public sealed class LaneMinion:MonoBehaviour
{
[SerializeField]private float moveSpeed=2.8f,detectionRange=6.8f,attackRange=1.75f,attackDamage=3.25f,attackCooldown=1.45f;private Health health;private int team;private Vector3 destination;private float nextAttackTime;public int Team=>team;private void Awake()=>health=GetComponent<Health>();public void Initialize(int teamId,Vector3 laneDestination){team=teamId;destination=laneDestination;nextAttackTime=Time.time+Random.Range(.25f,.8f);}
private void Update(){if(Time.timeScale<=0f||health==null||health.IsDead)return;Health target=FindTarget();if(target!=null){Vector3 delta=target.transform.position-transform.position;delta.y=0;float range=(target.GetComponent<LaneTower>()!=null||target.GetComponent<RealityCore>()!=null)?2.35f:attackRange;if(delta.sqrMagnitude<=range*range){Face(delta);if(Time.time>=nextAttackTime){nextAttackTime=Time.time+attackCooldown+Random.Range(0f,.18f);target.TakeDamage(attackDamage,gameObject);}return;}MoveTowards(target.transform.position);return;}RealityCore core=FindEnemyCore();if(!HasEnemyBastion()&&core!=null&&!core.GetComponent<Health>().IsDead){MoveTowards(core.transform.position);return;}MoveTowards(destination);}
private Health FindTarget(){Health best=null;float bestScore=float.MaxValue,maxSqr=detectionRange*detectionRange;foreach(Health candidate in FindObjectsByType<Health>()){if(candidate==null||candidate==health||candidate.IsDead)continue;bool enemy=false;float priority=1f;LaneMinion minion=candidate.GetComponent<LaneMinion>();if(minion!=null){enemy=minion.Team!=team;priority=.72f;}else{LaneTower tower=candidate.GetComponent<LaneTower>();if(tower!=null){enemy=tower.Team!=team;priority=.62f;}else{RealityCore core=candidate.GetComponent<RealityCore>();if(core!=null){enemy=core.Team!=team;priority=core.IsVulnerable?.48f:1.8f;}else{TeamMember member=candidate.GetComponent<TeamMember>();if(member!=null){enemy=member.Team!=team;priority=candidate.GetComponent<HeroIdentity>()!=null?1.22f:1f;}}}}if(!enemy)continue;Vector3 delta=candidate.transform.position-transform.position;delta.y=0;float sqr=delta.sqrMagnitude;if(sqr>maxSqr)continue;float score=sqr*priority;if(score<bestScore){bestScore=score;best=candidate;}}return best;}
private bool HasEnemyBastion(){foreach(LaneTower tower in FindObjectsByType<LaneTower>()){if(tower!=null&&tower.Team!=team){Health h=tower.GetComponent<Health>();if(h!=null&&!h.IsDead)return true;}}return false;}private RealityCore FindEnemyCore(){foreach(RealityCore core in FindObjectsByType<RealityCore>()){if(core!=null&&core.Team!=team)return core;}return null;}
private void MoveTowards(Vector3 point){Vector3 direction=point-transform.position;direction.y=0;if(direction.sqrMagnitude<.16f)return;direction.Normalize();transform.position+=direction*moveSpeed*Time.deltaTime;Face(direction);}private void Face(Vector3 direction){direction.y=0;if(direction.sqrMagnitude>.001f)transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(direction),10*Time.deltaTime);}
}
}